// Pseudo CKNE -> resource mapping
function mapCKNEToResources(ckne, base) {
  const maxConcurrent = Math.max(1, Math.round(ckne * 8));
  const spillBudget = base.spill * (1 - ckne);
  const memPerFragment = base.mem * (0.5 + 0.5 * ckne);
  return { maxConcurrent, spillBudget, memPerFragment };
}
```

